/// HarfBuzz's `has_arabic_joining` (`hb-ot-shaper-arabic-joining-list.hh`):
/// whether a script (ISO 15924 tag) has characters that join.
pub(crate) fn has_arabic_joining(script: [u8; 4]) -> bool {
    matches!(
        &script,
        b"Adlm"
            | b"Arab"
            | b"Chrs"
            | b"Rohg"
            | b"Mand"
            | b"Mani"
            | b"Mong"
            | b"Nkoo"
            | b"Ougr"
            | b"Phag"
            | b"Phlp"
            | b"Sogd"
            | b"Syrc"
    )
}
